938	// findRecordIn 在给定结算历史中按编号查找成功记录。
939	func findRecordIn(records []Record, id string) (Record, bool) {
940		// 记录按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
941		for _, r := range records {
942			if r.ID == id {
943				return r, true
944			}
945		}
946		return Record{}, false
947	}
948	
949	// validateRefundRequest 校验一项退款请求：退款编号、原付款编号、原因三者
950	// 都必须非空，校验顺序即对外约定（id → settlement_id → reason）。
951	// 未通过校验的编号不占用退款资格，之后可修改后重新提交。
952	func validateRefundRequest(req *RefundRequest) (string, bool) {
953		if req.ID == "" {
954			return reasonEmptyRefundID, false
955		}
956		if req.SettlementID == "" {
957			return reasonEmptySettlement, false
958		}
959		if req.Reason == "" {
960			return reasonEmptyReason, false
961		}
962		return "", true
963	}
964	
965	// attachRefundDetail 把一笔成功退款（首次成功或幂等重复携带的同一条原记录）
966	// 的统一详情填入逐项结果：原付款编号、账户、资产、退款总额、原因与完整退款
967	// 记录。首次成功与重复申请共用这一个出口，保证两者拼装出的详情逐字一致。
968	func attachRefundDetail(res *RefundResult, rec RefundRecord) {
969		res.Reason = rec.Reason
970		res.SettlementID = rec.SettlementID
971		res.Account = rec.Account
972		res.Asset = rec.Asset
973		res.Charged = rec.Charged
974		cp := rec
975		res.Record = &cp
976	}
977	
978	// judgeRefund 按退款规则评估一项请求，只读取状态 st，不产生任何副作用。
979	// 返回逐项结果；预计成功时结果只填编号，落账效果以 ledgerEffect 描述，
980	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功退款编号
981	// 的重复/冲突（优先于目标判断，即使新目标不存在也不退化成 not_found）、
982	// 目标结算存在性、目标是否已被其他退款编号退回。
983	func judgeRefund(req *RefundRequest, st *ledgerState) (RefundResult, *ledgerEffect) {
984		res := RefundResult{ID: req.ID}
985	
986		// 1. 参数校验。未通过的编号不占用退款资格。
987		if reason, ok := validateRefundRequest(req); !ok {
988			res.Status = StatusInvalid
989			res.Reason = reason
990			return res, nil
991		}
992	
993		// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
994		//    任一不同则冲突（即使新目标不存在也不能退化成 not_found）。
995		//    两者都不再入账。本批次内先成功的同编号项也在此被看到。
996		if prior, exists := findRefundIn(st.Refunds, req.ID); exists {
997			if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
998				res.Status = StatusDuplicate
999				attachRefundDetail(&res, prior)
1000			} else {
1001				res.Status = StatusConflict
1002				res.Reason = reasonRefundConflict
1003			}
1004			return res, nil
1005		}
1006	
1007		// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
1008		target, exists := findRecordIn(st.Settlements, req.SettlementID)
1009		if !exists {
1010			res.Status = StatusNotFound
1011			res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
1012			return res, nil
1013		}
1014	
1015		// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
1016		if prior, refunded := findRefundOfSettlementIn(st.Refunds, req.SettlementID); refunded {
1017			res.Status = StatusAlreadyRefunded
1018			res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
1019			return res, nil
1020		}
1021	
1022		// 5. 预计成功：全额（amount 与当时手续费一并，即以原结算的 charged 为准）
1023		//    退回原账户、原资产；序号按当前退款历史长度连续递增。
1024		rec := RefundRecord{
1025			ID:           req.ID,
1026			SettlementID: target.ID,
1027			Reason:       req.Reason,
1028			Account:      target.Account,
1029			Asset:        target.Asset,
1030			Amount:       target.Amount,
1031			Fee:          target.Fee,
1032			Charged:      target.Charged,
1033			AfterSeq:     int64(len(st.Settlements)),
1034			Seq:          int64(len(st.Refunds)) + 1,
1035		}
1036		return res, &ledgerEffect{
1037			key:    balanceKey{target.Account, target.Asset},
1038			delta:  target.Charged,
1039			refund: &rec,
1040		}
1041	}
1042	
1043	// runRefundBatch 按输入顺序在给定状态 st 上处理整个退款批次，返回逐项结果。
1044	// 退款规则（judgeRefund）与落账生效（commit）分离：规则只读取 st 给出判定
1045	// 和预计落账效果，不改动任何状态；生效策略与付款提交共用同一套
1046	// applyEffect/落盘/回滚步骤——真实提交先改内存再原子落盘、失败回滚并报告
1047	// storage_error。保存失败时 commit 已回滚该项（余额与退款历史恢复原样），
1048	// 该项不占退款编号、不把原付款标成已退款，前项成功保留、后项继续处理。
1049	// 调用方必须持有 reg.mu。
1050	func runRefundBatch(batch RefundBatch, st *ledgerState, commit commitEffect) []RefundResult {
1051		out := make([]RefundResult, 0, len(batch.Refunds))
1052		for i := range batch.Refunds {
1053			req := &batch.Refunds[i]
1054	
1055			// 1. 规则判定：纯读取，不产生任何副作用。
1056			res, eff := judgeRefund(req, st)
1057			if eff == nil {
1058				out = append(out, res)
1059				continue
1060			}
1061	
1062			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
1063			//    该项报告 storage_error，不留退款记录、不占退款序号，后项继续。
1064			if err := commit(st, *eff); err != nil {
1065				res.Status = StatusStorage
1066				res.Reason = err.Error()
1067				out = append(out, res)
1068				continue
1069			}
1070	
1071			// 3. 成功落账：与重复申请一样通过统一出口拼装详情。
1072			res.Status = StatusRefundSuccess
1073			attachRefundDetail(&res, *eff.refund)
1074			out = append(out, res)
1075		}
1076		return out
1077	}
1078	
1079	// findRefundIn 在给定退款历史中按编号查找成功记录。
1080	func findRefundIn(refunds []RefundRecord, id string) (RefundRecord, bool) {
1081		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
1082		for _, r := range refunds {
1083			if r.ID == id {
1084				return r, true
1085			}
1086		}
1087		return RefundRecord{}, false
1088	}
