1139	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
1140	func (l *Ledger) Query() (*Snapshot, error) {
1141		if err := l.beginOp(); err != nil {
1142			return nil, err
1143		}
1144		defer l.endOp()
1145		l.reg.mu.Lock()
1146		defer l.reg.mu.Unlock()
1147	
1148		st := l.stateView()
1149		bals := make([]BalanceView, 0, len(st.Balances))
1150		for k, v := range st.Balances {
1151			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
1152		}
1153		sortBalances(bals)
1154		recs := make([]Record, len(st.Settlements))
1155		copy(recs, st.Settlements)
1156		refunds := make([]RefundRecord, len(st.Refunds))
1157		copy(refunds, st.Refunds)
1158		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
1159	}
1160	
1161	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
1162	func (l *Ledger) Balance(account, asset string) (int64, error) {
1163		if err := l.beginOp(); err != nil {
1164			return 0, err
1165		}
1166		defer l.endOp()
1167		l.reg.mu.Lock()
1168		defer l.reg.mu.Unlock()
1169		return l.stateView().Balances[balanceKey{account, asset}], nil
1170	}
1171	
1172	func sortBalances(bals []BalanceView) {
1173		sort.Slice(bals, func(i, j int) bool {
1174			if bals[i].Account != bals[j].Account {
1175				return bals[i].Account < bals[j].Account
1176			}
1177			return bals[i].Asset < bals[j].Asset
1178		})
1179	}
1180	
1181	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
1182	func (l *Ledger) persistLocked() error {
1183		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
1184			return ledgerError(ErrStorage, "injected write failure")
1185		}
1186		return atomicWrite(l.path, l.stateView())
1187	}
1188	
1189	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
1190	func SetFailHook(l *Ledger, fw FailWriter) {
1191		l.reg.failHook = fw
