12	// 本文件为公开查询（Ledger.Query）补充两个账本句柄交错使用下的回归保障：
13	// 同一进程中两个句柄指向同一本账本时，一个句柄正在提交有序退款批次（批次
14	// 仍在逐项保存、账本互斥锁尚未释放），另一个句柄调用公开的 Ledger.Query。
15	// 查询必须等该退款批次整批处理完毕，再返回“余额 + 付款历史 + 退款历史”
16	// 共同对应批次结束后完整状态的同一份快照：
17	//   - 不能提前返回批次前的旧快照；
18	//   - 不能只读到前半段已经成功的退款（第一笔已落账、第二笔尚未确定的中途状态）；
19	//   - 不能把刚增加但尚未保存成功的余额当成可见余额；
20	//   - 正常等待不得报账本关闭（ledger_closed）或存储错误（storage_error）。
21	//
22	// 场景固定为：一个账户 aa、两种资产（usdc 发生业务、eth 全程不动），
23	// usdc 初始余额 10000。先成功支付两笔引用编号不同的付款，两笔都实际扣除了
24	// 非零手续费：
25	//
26	//	p1=1000，100bps：手续费 10，扣款总额 1010；
27	//	p2=2000， 50bps：手续费 10，扣款总额 2010。
28	//
29	// 付款后 usdc 余额为 10000-3020=6980。退款批次按顺序用 r1 退回 p1、
30	// 用 r2 退回 p2，退款编号与原因均合法；在 r2 的“保存点”用故障注入门把
31	// 批次停住（此时 r1 已完整落账、锁仍被退款句柄持有），另一句柄就在此刻
32	// 发起 Query。随后放行 r2 的保存，分别覆盖两种完整结局：
33	//   - 两笔退款都保存成功：余额回补两笔原付款扣款总额 3020（手续费一并退回），
34	//     usdc 回到 10000；退款历史为按成功顺序排列的 r1、r2 两条成功记录，
35	//     每条保留退款编号、原因与原付款编号，金额与手续费来自各自原结算；
36	//   - r1 成功、r2 保存失败：第一笔成功保留，批次第二项为 storage_error；
37	//     查询本身正常成功，余额只回补第一笔原付款扣款 1010（usdc=7990），
38	//     退款历史只有 r1 一条成功记录——失败申请不留退款记录、不虚增余额、
39	//     不占用退款成功序号（r1 仍为 seq 1）。
40	//
41	// 两种结局中两笔原付款历史的内容与顺序都保持不变；查询是只读操作：
42	// 查询期间账本的变化只能来自正在执行的退款，查询结束后再次读取得到相同的
43	// 业务状态，查询本身不额外写盘、不产生任何记录。全部行为只使用既有公开
44	// 接口与测试故障注入，可在本机离线稳定复现。
45	
46	// runQueryDuringRefundInterleave 执行交错用例。failSecond=false 时 r1、r2
47	// 都真实保存成功；failSecond=true 时 r1 成功、r2 在保存点失败
48	//（storage_error，回滚）。
49	func runQueryDuringRefundInterleave(t *testing.T, failSecond bool) {
50		t.Helper()
51		const (
52			acct, asset = "aa", "usdc"
53			other       = "eth" // 全程不发生收支的资产，用来锁定余额排序与无关余额不变
54			initialUSDC = int64(10000)
55			initialETH  = int64(5)
56		)
57	
58		// 两笔原付款：编号不同，手续费均为非零并实际扣除。
59		// p1: 1000 + 100bps*1000(=10) = 1010
60		// p2: 2000 +  50bps*2000(=10) = 2010
61		wantP1 := Record{
62			ID: "p1", Account: acct, Paymaster: "pm", Asset: asset,
63			Amount: 1000, Nonce: 1, FeeBps: 100, Fee: 10, Charged: 1010, Seq: 1,
64		}
65		wantP2 := Record{
66			ID: "p2", Account: acct, Paymaster: "pm", Asset: asset,
67			Amount: 2000, Nonce: 1, FeeBps: 50, Fee: 10, Charged: 2010, Seq: 2,
68		}
69		wantPayments := []Record{wantP1, wantP2}
70	
71		// 退款落账时两笔结算都已存在：after_seq=2。
72		wantR1 := RefundRecord{
73			ID: "r1", SettlementID: "p1", Reason: "cancel p1",
74			Account: acct, Asset: asset, Amount: 1000, Fee: 10, Charged: 1010,
75			AfterSeq: 2, Seq: 1,
76		}
77		wantR2 := RefundRecord{
78			ID: "r2", SettlementID: "p2", Reason: "cancel p2",
79			Account: acct, Asset: asset, Amount: 2000, Fee: 10, Charged: 2010,
80			AfterSeq: 2, Seq: 2,
81		}
82	
83		// 两种结局的完整账本状态。
84		wantRefundStatuses := []string{StatusRefundSuccess, StatusRefundSuccess}
85		wantBalanceUSDC := initialUSDC // 10000-3020+1010+2010
86		wantRefunds := []RefundRecord{wantR1, wantR2}
87		if failSecond {
88			// r1 成功、r2 保存失败：只回补第一笔原付款扣款 1010。
89			wantRefundStatuses = []string{StatusRefundSuccess, StatusStorage}
90			wantBalanceUSDC = 7990 // 10000-3020+1010
91			wantRefunds = []RefundRecord{wantR1}
92		}
93		// 余额始终按账户、资产排序：aa/eth 在 aa/usdc 之前；无关资产 eth 不动。
94		wantBalances := []BalanceView{
95			{Account: acct, Asset: other, Balance: initialETH},
96			{Account: acct, Asset: asset, Balance: wantBalanceUSDC},
97		}
98	
99		path := newTestLedger(t, []BalanceInit{
100			{Account: acct, Asset: asset, Balance: initialUSDC},
101			{Account: acct, Asset: other, Balance: initialETH},
102		})
103		lRefund := openOrFail(t, path) // 句柄 A：提交退款批次
104		lQuery := openOrFail(t, path)  // 句柄 B：公开查询（同一进程、同一本账本）
105	
106		// 先顺序成功支付 p1、p2。
107		if r := mustSettle(t, lRefund, 100, intent("p1", acct, asset, 1000)); r.Status != StatusSettled {
108			t.Fatalf("settle p1: %+v", r)
109		}
110		if r := mustSettle(t, lRefund, 50, intent("p2", acct, asset, 2000)); r.Status != StatusSettled {
111			t.Fatalf("settle p2: %+v", r)
112		}
113		if r1 := mustSettle(t, lRefund, 100, intent("p1", acct, asset, 1000)); r1.Status != StatusDuplicate {
114			t.Fatalf("setup sanity: p1 retry want duplicate, got %+v", r1)
115		}
116		if bal, _ := lRefund.Balance(acct, asset); bal != 6980 {
117			t.Fatalf("balance after payments=%d want 6980", bal)
118		}
119	
120		// 故障注入门安装在付款完成之后：第 1 次持久化（r1）正常通过，
121		// 第 2 次持久化（r2 的保存点）停住，放行后按 failSecond 决定成败。
122		gate := &secondPersistGate{
123			reached: make(chan struct{}),
124			release: make(chan struct{}),
125			fail:    failSecond,
126		}
127		SetFailHook(lRefund, gate)
128	
129		var (
130			wg sync.WaitGroup
131	
132			refundRes    *RefundBatchResult
133			refundErr    error
134			queryStarted = make(chan struct{})
135			queryDone    = make(chan struct{}) // Query 返回（无论成功失败）后关闭
136			snap         *Snapshot
137			queryErr     error
138		)
139	
140		// 句柄 A：顺序提交退款 r1、r2。r2 的保存会停在 gate，整批持锁不释放。
141		wg.Add(1)
142		go func() {
143			defer wg.Done()
144			refundRes, refundErr = lRefund.Refund(RefundBatch{Refunds: []RefundRequest{
145				refundReq("r1", "p1", "cancel p1"),
146				refundReq("r2", "p2", "cancel p2"),
147			}})
148		}()
149	
150		// 等 A 把 r1 完整落账、停在 r2 的保存点（批次仍在保存、锁仍被持有）。
151		<-gate.reached
152	
153		// 句柄 B：就在该退款批次仍在保存时调用公开 Query。它应当在同一把账本锁上
154		// 排队，直到 A 整批处理完毕，而不是读到 r1 已退、r2 未定的中途状态。
155		wg.Add(1)
156		go func() {
157			defer wg.Done()
158			defer close(queryDone)
159			close(queryStarted)
160			snap, queryErr = lQuery.Query()
161		}()
162	
163		<-queryStarted
164		// 让出 P，令查询 goroutine 实际运行到争夺账本锁并排队；A 仍停在 r2 保存点。
165		for i := 0; i < 4; i++ {
166			runtime.Gosched()
167		}
168		// 退款批次仍在保存、锁仍被 A 持有：查询绝不可能在此刻返回。正确实现下查询
169		// goroutine 正阻塞在同一把账本锁上，因此该非阻塞检查不会误报。它直接锁定
170		// “查询等待在途退款批次整批完成”这一性质——仅凭结果无法区分等待与否：
171		// r2 最终失败时，批次结束状态与“r1 已落账、r2 未定”的中途状态余额恰好
172		// 相同，本检查补上这重保障，杜绝查询在失败结局下提前返回中途快照。
173		select {
174		case <-queryDone:
175			t.Fatal("Query returned while the refund batch was still saving; it must wait for the whole batch")
176		default:
177		}
178		close(gate.release) // 放行 r2 保存（成功或失败），随后整批结束并释放锁
179		wg.Wait()
180	
181		SetFailHook(lRefund, nil) // 用例结束，拆卸故障注入
182	
183		if refundErr != nil {
184			t.Fatalf("refund batch: %v", refundErr)
185		}
186		// 查询正常等待并成功：不得因为等待在途批次而报账本关闭或存储错误。
187		if queryErr != nil {
188			t.Fatalf("Query during in-flight refund batch must succeed after waiting, got kind=%s err=%v",
189				KindOf(queryErr), queryErr)
190		}
191	
192		// ---- 退款批次逐项结果：与输入顺序一一对应，各自独立处理 ----
193		if got := refundStatuses(refundRes); !reflect.DeepEqual(got, wantRefundStatuses) {
194			t.Fatalf("refund statuses=%v want %v", got, wantRefundStatuses)
195		}
196		if refundRes.Results[0].ID != "r1" || refundRes.Results[1].ID != "r2" {
197			t.Fatalf("refund results out of order: %+v", refundRes.Results)
198		}
199		assertRefundResultRecord(t, refundRes.Results[0], StatusRefundSuccess, wantR1)
200		if failSecond {
201			// r2 保存失败：storage_error、无退款记录、无成功详情；前项 r1 保留不回滚。
202			r2 := refundRes.Results[1]
203			if r2.Status != StatusStorage {
204				t.Fatalf("r2 status=%s want storage_error", r2.Status)
205			}
206			if r2.Record != nil {
207				t.Fatalf("failed r2 must not carry a refund record: %+v", r2.Record)
208			}
209			if r2.SettlementID != "" || r2.Account != "" || r2.Asset != "" || r2.Charged != 0 {
210				t.Fatalf("storage_error must not carry success detail: %+v", r2)
211			}
212			if r2.Reason == "" {
213				t.Fatalf("storage_error must carry the failure explanation")
214			}
215		} else {
216			assertRefundResultRecord(t, refundRes.Results[1], StatusRefundSuccess, wantR2)
217		}
218	
219		// ---- 交错查询返回的快照：余额、付款历史、退款历史共同对应批次结束后的
220		// 同一个完整状态，绝不可能是旧快照、只有 r1 的快照或未确认的 r2 ----
221		if !reflect.DeepEqual(snap.Balances, wantBalances) {
222			t.Fatalf("interleaved query balances:\n got %#v\nwant %#v", snap.Balances, wantBalances)
223		}
224		if !reflect.DeepEqual(snap.Settlements, wantPayments) {
225			t.Fatalf("interleaved query payment history:\n got %#v\nwant %#v", snap.Settlements, wantPayments)
226		}
227		if !reflect.DeepEqual(snap.Refunds, wantRefunds) {
228			t.Fatalf("interleaved query refund history:\n got %#v\nwant %#v", snap.Refunds, wantRefunds)
229		}
230		// 显式锁定失败结局的关键不变量：失败申请不留记录、不占成功序号、不虚增余额。
231		if failSecond {
232			if len(snap.Refunds) != 1 || snap.Refunds[0].ID != "r1" || snap.Refunds[0].Seq != 1 {
233				t.Fatalf("failed r2 must leave exactly one successful refund at seq 1: %+v", snap.Refunds)
234			}
235			for _, rf := range snap.Refunds {
236				if rf.ID == "r2" || rf.SettlementID == "p2" {
237					t.Fatalf("failed refund must not appear in history: %+v", rf)
238				}
239			}
240			if got := snap.Balances[1].Balance; got != 7990 {
241				t.Fatalf("balance must only include the first refund (1010): got %d want 7990", got)
242			}
243		} else {
244			// 成功结局：两条成功记录按成功顺序排列，金额与手续费来自各自原结算。
245			if snap.Refunds[0].Seq != 1 || snap.Refunds[1].Seq != 2 ||
246				snap.Refunds[0].ID != "r1" || snap.Refunds[1].ID != "r2" ||
247				snap.Refunds[0].SettlementID != "p1" || snap.Refunds[1].SettlementID != "p2" ||
248				snap.Refunds[0].Reason != "cancel p1" || snap.Refunds[1].Reason != "cancel p2" ||
249				snap.Refunds[0].Amount != 1000 || snap.Refunds[0].Fee != 10 || snap.Refunds[0].Charged != 1010 ||
250				snap.Refunds[1].Amount != 2000 || snap.Refunds[1].Fee != 10 || snap.Refunds[1].Charged != 2010 {
251				t.Fatalf("successful refund history must keep id/reason/original payment, amounts and fees: %+v", snap.Refunds)
252			}
253		}
254	
255		// ---- 查询只读且可重复：查询结束后用两个句柄分别再次读取，业务状态相同；
256		// 查询本身不改写账本文件、不产生任何记录 ----
257		againFromQuery := mustQuery(t, lQuery)
258		if !reflect.DeepEqual(againFromQuery, snap) {
259			t.Fatalf("re-query via query handle differs from the interleaved snapshot:\n got %+v\nwant %+v",
260				againFromQuery, snap)
261		}
262		againFromRefund := mustQuery(t, lRefund)
263		if !reflect.DeepEqual(againFromRefund, snap) {
264			t.Fatalf("query via refund handle differs:\n got %+v\nwant %+v", againFromRefund, snap)
265		}
266	
267		before, err := os.ReadFile(path)
268		if err != nil {
269			t.Fatal(err)
270		}
271		onceMore := mustQuery(t, lQuery)
272		if !reflect.DeepEqual(onceMore, snap) {
273			t.Fatalf("query must be repeatable with identical business state: %+v", onceMore)
274		}
275		after, err := os.ReadFile(path)
276		if err != nil {
277			t.Fatal(err)
278		}
279		if !bytes.Equal(before, after) {
280			t.Fatalf("Query rewrote the ledger file:\nbefore=%s\nafter =%s", before, after)
281		}
282	
283		// 失败申请的原因不落盘；成功记录（含各自原因）必须在磁盘上。
284		if failSecond && bytes.Contains(after, []byte("cancel p2")) {
285			t.Fatalf("failed refund request persisted to ledger file:\n%s", after)
286		}
287		if !bytes.Contains(after, []byte(`"id":"r1"`)) ||
288			!bytes.Contains(after, []byte(`"settlement_id":"p1"`)) ||
289			!bytes.Contains(after, []byte(`"reason":"cancel p1"`)) {
290			t.Fatalf("successful r1 missing from ledger file:\n%s", after)
291		}
292	
293		// 关闭后重开（新进程语义）：磁盘上的完整账本与交错查询结果逐字段一致，
294		// 两种结局都可在本机离线复现。
295		if err := lRefund.Close(); err != nil {
296			t.Fatal(err)
297		}
298		if err := lQuery.Close(); err != nil {
299			t.Fatal(err)
300		}
301		reopened := openOrFail(t, path)
302		snapDisk := mustQuery(t, reopened)
303		if !reflect.DeepEqual(snapDisk.Balances, wantBalances) {
304			t.Fatalf("reopened balances:\n got %#v\nwant %#v", snapDisk.Balances, wantBalances)
305		}
306		if !reflect.DeepEqual(snapDisk.Settlements, wantPayments) {
307			t.Fatalf("reopened payment history:\n got %#v\nwant %#v", snapDisk.Settlements, wantPayments)
308		}
309		if !reflect.DeepEqual(snapDisk.Refunds, wantRefunds) {
310			t.Fatalf("reopened refund history:\n got %#v\nwant %#v", snapDisk.Refunds, wantRefunds)
311		}
312	}
