314	// TestQueryWaitsForInFlightRefundBatchBothRefunded：两笔退款都保存成功。
315	// 与退款批次并发发起的公开 Query 必须等整批结束：余额包含两笔原付款扣款
316	// 总额 3020 的回补（手续费一并退回），usdc 回到 10000、无关资产 eth 不变；
317	// 退款历史为按成功顺序排列的 r1、r2 两条成功记录；两笔原付款历史保持原样。
318	func TestQueryWaitsForInFlightRefundBatchBothRefunded(t *testing.T) {
319		runQueryDuringRefundInterleave(t, false)
320	}
321	
322	// TestQueryWaitsForInFlightRefundBatchSecondSaveFails：r1 成功、r2 保存失败。
323	// 批次第二项为 storage_error 而并发 Query 正常成功；余额只回补第一笔原付款
324	// 扣款 1010（usdc=7990），退款历史只有 r1（seq 1）——失败的 r2 不留记录、
325	// 不虚增余额、不占用成功序号；两笔原付款历史的内容与顺序保持不变。
