32	func mustSettle(t *testing.T, l *Ledger, bps int, it PaymentIntent) ItemResult {
33		t.Helper()
34		res, err := l.Submit(FeeBatch{FeeBps: bps, Intents: []PaymentIntent{it}})
35		if err != nil {
36			t.Fatalf("submit %q: %v", it.ID, err)
37		}
38		return res.Results[0]
39	}
