	r1 := res.Results[0]
	if r1.Record == nil || r1.Record.Seq != 1 || r1.Record.Charged != 70 {
		t.Fatalf("predicted record: %+v", r1.Record)
	}
	if res.Results[1].Record != nil {
		t.Fatalf("failed preview item must not carry a record: %+v", res.Results[1])
	}
}

